const input = $input.first()?.json ?? {};

let workflow = input.workflow ?? input;

if (typeof workflow === 'string') {
  try {
    workflow = JSON.parse(workflow);
  } catch (error) {
    return [{
      json: {
        auditor_version: 'APA-V1',
        status: 'INVALID_INPUT',
        error: 'workflow is not valid JSON',
        message: error.message
      }
    }];
  }
}

const evidence = [];
const findings = [];

function addEvidence(ruleId, status, severity, title, observed, path = null) {
  const item = {
    rule_id: ruleId,
    status,
    severity,
    title,
    observed,
    path
  };

  evidence.push(item);

  if (status === 'FAIL') {
    findings.push(item);
  }
}

function walk(value, path, visitor) {
  if (value === null || value === undefined) return;

  visitor(value, path);

  if (Array.isArray(value)) {
    value.forEach((v, i) => walk(v, `${path}[${i}]`, visitor));
    return;
  }

  if (typeof value === 'object') {
    Object.entries(value).forEach(([key, val]) => {
      walk(val, `${path}.${key}`, visitor);
    });
  }
}

if (!workflow || typeof workflow !== 'object' || Array.isArray(workflow)) {
  return [{
    json: {
      auditor_version: 'APA-V1',
      status: 'INVALID_INPUT',
      error: 'Workflow must be a JSON object.'
    }
  }];
}

const nodes = Array.isArray(workflow.nodes) ? workflow.nodes : [];

// APA-WF-001
addEvidence(
  'APA-WF-001',
  typeof workflow.name === 'string' && workflow.name.trim().length > 0 ? 'PASS' : 'FAIL',
  'ERROR',
  'Workflow must have a name',
  workflow.name ?? null,
  '.name'
);

// APA-WF-002
addEvidence(
  'APA-WF-002',
  nodes.length > 0 ? 'PASS' : 'FAIL',
  'ERROR',
  'Workflow must contain nodes',
  {
    node_count: nodes.length
  },
  '.nodes'
);

// APA-WF-003
const pinData = workflow.pinData;
const hasPinnedData =
  pinData &&
  typeof pinData === 'object' &&
  !Array.isArray(pinData) &&
  Object.keys(pinData).length > 0;

addEvidence(
  'APA-WF-003',
  hasPinnedData ? 'FAIL' : 'PASS',
  'WARNING',
  'Pinned execution data must not be present',
  {
    present: hasPinnedData,
    keys: hasPinnedData ? Object.keys(pinData) : []
  },
  '.pinData'
);

// APA-WF-004
const plainHttp = [];

walk(workflow, '$', (value, path) => {
  if (typeof value === 'string' && /^http:\/\//i.test(value.trim())) {
    plainHttp.push({
      path,
      value: value.trim()
    });
  }
});

addEvidence(
  'APA-WF-004',
  plainHttp.length === 0 ? 'PASS' : 'FAIL',
  'ERROR',
  'Plain HTTP endpoints are forbidden',
  {
    count: plainHttp.length,
    matches: plainHttp
  },
  '$'
);

// APA-WF-005
const secretMatches = [];
const secretKeyPattern =
  /(password|passwd|secret|api[_-]?key|access[_-]?token|auth[_-]?token|private[_-]?key)/i;

walk(workflow, '$', (value, path) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return;

  for (const [key, val] of Object.entries(value)) {
    if (!secretKeyPattern.test(key)) continue;
    if (typeof val !== 'string') continue;
    if (val.length < 8) continue;
    if (val.startsWith('={{') || val.includes('$env.') || val.includes('$vars.')) continue;

    secretMatches.push({
      path: `${path}.${key}`,
      key,
      value_length: val.length
    });
  }
});

addEvidence(
  'APA-WF-005',
  secretMatches.length === 0 ? 'PASS' : 'FAIL',
  'ERROR',
  'Secret-like hardcoded values are forbidden',
  {
    count: secretMatches.length,
    matches: secretMatches
  },
  '$'
);

// APA-WF-006
const webhooks = nodes.filter(
  node =>
    typeof node.type === 'string' &&
    (
      node.type === 'n8n-nodes-base.webhook' ||
      node.type.toLowerCase().includes('webhook')
    )
);

const unauthenticatedWebhooks = webhooks.filter(node => {
  const authentication =
    node.parameters?.authentication ??
    node.parameters?.authType ??
    node.parameters?.authenticationType ??
    'none';

  return !authentication || authentication === 'none';
});

addEvidence(
  'APA-WF-006',
  unauthenticatedWebhooks.length === 0 ? 'PASS' : 'FAIL',
  'ERROR',
  'Webhook triggers must use authentication',
  {
    webhook_count: webhooks.length,
    unauthenticated: unauthenticatedWebhooks.map(node => ({
      name: node.name,
      type: node.type
    }))
  },
  '.nodes'
);

// APA-WF-007
const errorWorkflow =
  workflow.settings?.errorWorkflow ??
  workflow.errorWorkflow ??
  null;

addEvidence(
  'APA-WF-007',
  errorWorkflow ? 'PASS' : 'FAIL',
  'WARNING',
  'Workflow should define an error workflow',
  {
    configured: Boolean(errorWorkflow),
    value: errorWorkflow
  },
  '.settings.errorWorkflow'
);

const errorCount = findings.filter(f => f.severity === 'ERROR').length;
const warningCount = findings.filter(f => f.severity === 'WARNING').length;

const status =
  errorCount > 0
    ? 'FAIL'
    : warningCount > 0
      ? 'PASS_WITH_WARNINGS'
      : 'PASS';

const passed = evidence.filter(e => e.status === 'PASS').length;
const failed = evidence.filter(e => e.status === 'FAIL').length;

return [{
  json: {
    auditor_version: 'APA-V1',
    policy_id: 'APA-V1-DEFAULT',
    policy_version: '1.0.0',
    status,
    summary: {
      workflow_name: workflow.name ?? null,
      workflow_id: workflow.id ?? null,
      node_count: nodes.length,
      rules_total: evidence.length,
      rules_passed: passed,
      rules_failed: failed,
      errors: errorCount,
      warnings: warningCount
    },
    evidence,
    findings,
    generated_at: new Date().toISOString()
  }
}];
